import pandas as pd
import numpy as np

# Load data
no2_df = pd.read_csv('chunks_csv/moran_local_no2crime_no2_Q4_2022.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Step 1: Handle missing values
clean_df = no2_df.dropna().reset_index(drop=True)
data_points_used = len(clean_df)
print(f'data_points_used = {data_points_used}')

# Step 2: Map adjacency list
boroughs_in_clean = set(clean_df['borough'])
adjacency_clean = adjacency_df[
    adjacency_df['borough'].isin(boroughs_in_clean) &
    adjacency_df['neighbor'].isin(boroughs_in_clean)
]
adj_dict = adjacency_clean.groupby('borough')['neighbor'].apply(list).to_dict()

# Step 3: Compute overall statistics
overall_mean = clean_df['value'].mean()
overall_std = clean_df['value'].std()

# Step 4: Local spatial analysis
boro_indices = {row['borough']: idx for idx, row in clean_df.iterrows()}
neighbor_indices = {}
for boro in clean_df['borough']:
    if boro in adj_dict:
        neighbor_indices[boro] = [boro_indices[neighbor] for neighbor in adj_dict[boro] if neighbor in boro_indices]
    else:
        neighbor_indices[boro] = []

original_z = {}
original_neighbor_z_avg = {}

for index, row in clean_df.iterrows():
    boro = row['borough']
    value = row['value']
    if boro not in neighbor_indices or len(neighbor_indices[boro]) == 0:
        continue
    neighbor_values = [clean_df.iloc[idx]['value'] for idx in neighbor_indices[boro]]
    avg_neighbor = np.mean(neighbor_values)
    z_boro = (value - overall_mean) / overall_std
    z_neighbor = (avg_neighbor - overall_mean) / overall_std
    original_z[boro] = z_boro
    original_neighbor_z_avg[boro] = z_neighbor

# Step 5: Identify candidates
candidates = []
for boro in clean_df['borough']:
    if boro not in original_z or boro not in original_neighbor_z_avg:
        continue
    z_boro = original_z[boro]
    z_neighbor = original_neighbor_z_avg[boro]
    if z_boro >= 1.96 and z_neighbor >= 1.96:
        candidates.append((boro, 'HH', z_boro, z_neighbor))
    elif z_boro <= -1.96 and z_neighbor <= -1.96:
        candidates.append((boro, 'LL', z_boro, z_neighbor))

# Step 6: Permutation testing
num_permutations = 500
p_values = {}

for boro, boro_type, z_boro, z_neighbor in candidates:
    boro_idx = boro_indices[boro]
    neighbor_idx_list = neighbor_indices[boro]
    count = 0
    for _ in range(num_permutations):
        permuted_values = np.random.permutation(clean_df['value'].values)
        permuted_boro_value = permuted_values[boro_idx]
        permuted_neighbor_values = [permuted_values[idx] for idx in neighbor_idx_list]
        avg_neighbor_perm = np.mean(permuted_neighbor_values)
        z_boro_perm = (permuted_boro_value - overall_mean) / overall_std
        z_neighbor_perm = (avg_neighbor_perm - overall_mean) / overall_std
        if boro_type == 'HH':
            if z_boro_perm >= 1.96 and z_neighbor_perm >= 1.96:
                count += 1
        elif boro_type == 'LL':
            if z_boro_perm <= -1.96 and z_neighbor_perm <= -1.96:
                count += 1
    p = count / num_permutations
    p_values[boro] = (boro_type, z_boro, z_neighbor, p)

# Step 7: Final classification
significant_boroughs = []
for boro, (boro_type, z_boro, z_neighbor, p) in p_values.items():
    if p < 0.05:
        significant_boroughs.append((boro, boro_type, z_boro, z_neighbor, p))

# Step 8: Report results
result = []
for boro, boro_type, z_boro, z_neighbor, p in significant_boroughs:
    result.append(f"{boro} ({boro_type}, statistical method=z-score={z_boro:.4f}, p-value={p:.4f})")

if result:
    print("FINAL ANSWER: " + ", ".join(result))
else:
    print("FINAL ANSWER: none")
